package com.example.lovenotes;
import android.content.Context;
import android.security.keystore.KeyGenParameterSpec;
import android.security.keystore.KeyProperties;
import android.util.Base64;
import java.net.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.security.KeyStore;
import javax.crypto.*;import javax.crypto.spec.GCMParameterSpec;import org.json.JSONObject;
final class Connection {
 static final String ORIGIN=BuildConfig.SERVER_ORIGIN,ALIAS="LoveWidgetKey";
 static javax.crypto.SecretKey key() throws Exception {KeyStore store=KeyStore.getInstance("AndroidKeyStore");store.load(null);if(!store.containsAlias(ALIAS)){KeyGenerator generator=KeyGenerator.getInstance(KeyProperties.KEY_ALGORITHM_AES,"AndroidKeyStore");generator.init(new KeyGenParameterSpec.Builder(ALIAS,KeyProperties.PURPOSE_ENCRYPT|KeyProperties.PURPOSE_DECRYPT).setBlockModes(KeyProperties.BLOCK_MODE_GCM).setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE).build());generator.generateKey();}return (javax.crypto.SecretKey)store.getKey(ALIAS,null);}
 static void save(Context c,String token) throws Exception {Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.ENCRYPT_MODE,key());String value=Base64.encodeToString(cipher.getIV(),Base64.NO_WRAP)+":"+Base64.encodeToString(cipher.doFinal(token.getBytes(StandardCharsets.UTF_8)),Base64.NO_WRAP);c.getSharedPreferences("widget",0).edit().putString("token",value).apply();}
 static String token(Context c) throws Exception {String value=c.getSharedPreferences("widget",0).getString("token",null);if(value==null)return null;String[] parts=value.split(":");Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.DECRYPT_MODE,key(),new GCMParameterSpec(128,Base64.decode(parts[0],Base64.NO_WRAP)));return new String(cipher.doFinal(Base64.decode(parts[1],Base64.NO_WRAP)),StandardCharsets.UTF_8);}
 static JSONObject request(String path,String token,JSONObject data) throws Exception {HttpURLConnection conn=(HttpURLConnection)new URL(ORIGIN+path).openConnection();conn.setConnectTimeout(4000);conn.setReadTimeout(4000);conn.setInstanceFollowRedirects(false);if(token!=null)conn.setRequestProperty("Authorization","Bearer "+token);try{if(data!=null){conn.setRequestMethod("POST");conn.setDoOutput(true);conn.setRequestProperty("Content-Type","application/json");try(OutputStream out=conn.getOutputStream()){out.write(data.toString().getBytes(StandardCharsets.UTF_8));}}int code=conn.getResponseCode();InputStream stream=code>=200&&code<300?conn.getInputStream():conn.getErrorStream();if(stream==null)throw new IOException("Please check your connection.");ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(InputStream input=stream){byte[] buffer=new byte[2048];int n;while((n=input.read(buffer))!=-1){bytes.write(buffer,0,n);if(bytes.size()>32768)throw new IOException("Unexpected response.");}}JSONObject result=new JSONObject(bytes.toString("UTF-8"));if(code<200||code>=300)throw new IOException(result.optString("error","Please try again."));return result;}finally{conn.disconnect();}}
}
